_settings.CustomThemeColorArgb    = newCustomColorArgb;
_settings.SkipThemeRestartPrompt  = newSkipThemePrompt;
_settings.DefaultNativeSessionColor = newDefaultNativeColor;
_settings.ShowInlineUsageBars    = newShowInlineBars;
_settings.ShowSubagentCount      = newShowSubagentCount;

// Chat tab captions only need a refresh; a new AI/title choice applies from the next chat.
ChatIconStyle newChatIconStyle = modernIconsRadio.IsChecked == true ? ChatIconStyle.Modern : ChatIconStyle.Classic;
ChatWorkingTabIcon newWorkingTabIcon = (workingIconCombo.SelectedItem as ComboBoxItem)?.Tag is ChatWorkingTabIcon pickedIcon
    ? pickedIcon
    : _settings.ChatWorkingTabIcon;
bool chatIconStyleChanged = newChatIconStyle != _settings.ChatIconStyle;
bool chatTabCaptionsChanged = (showChatTabStatusCheck.IsChecked == true) != _settings.ShowChatTabStatus
                              || (autoTitleCheck.IsChecked == true) != _settings.AutoTitleChatTabs
                              || chatIconStyleChanged
                              || newWorkingTabIcon != _settings.ChatWorkingTabIcon;
_settings.ShowChatTabStatus       = showChatTabStatusCheck.IsChecked == true;
_settings.AutoTitleChatTabs       = autoTitleCheck.IsChecked == true;
_settings.AutoTitleChatTabsWithAi = autoTitleAiCheck.IsChecked == true;
_settings.ShowChatTokenCounts     = showTokenCountsCheck.IsChecked == true;
_settings.ExpandFailedToolCalls   = expandFailedToolsCheck.IsChecked == true;
if ((thinkingCombo.SelectedItem as ComboBoxItem)?.Tag is ChatThinkingDisplay thinkingDisplay)
{
    _settings.ChatThinkingDisplay = thinkingDisplay;
}
_settings.PlainChatWorkingStatus  = plainWorkingStatusCheck.IsChecked == true;
UI.ChatTranscriptView.PlainWorkingStatus = _settings.PlainChatWorkingStatus;

// Open chats switch at once: their XAML captions follow on their own, the rest is redone here.
string newChatLanguage = (chatLanguageCombo.SelectedItem as ComboBoxItem)?.Tag as string ?? origChatLanguage;
if (!string.Equals(newChatLanguage, origChatLanguage, StringComparison.OrdinalIgnoreCase))
{
    _settings.ChatLanguage = newChatLanguage;
    ApplyChatLanguage();
    RefreshChatLanguage();
}
_settings.ChatIconStyle           = newChatIconStyle;
_settings.ChatWorkingTabIcon      = newWorkingTabIcon;
bool compactToolbarChanged = (compactToolbarCheck.IsChecked == true) != _settings.CompactChatToolbar;
_settings.CompactChatToolbar = compactToolbarCheck.IsChecked == true;
if (chatIconStyleChanged || compactToolbarChanged)
{
    ApplyChatIconStyle();
}
if (chatIconStyleChanged)
{
    RefreshAllAttachmentChips();
}
_settings.UsageAutoRefreshSeconds = newAutoRefresh;
_settings.PromptFontSize          = newFontSize;

public ChatThinkingDisplay ChatThinkingDisplay { get; set; } = ChatThinkingDisplay.Collapsed;

/// <summary>
/// If true, the native chat's live status line always says "Thinking…" instead of rotating
/// through playful verbs ("Pondering…", "Noodling…"). Off by default.
/// </summary>
public bool PlainChatWorkingStatus { get; set; }

/// <summary>
/// If true, the native chat's toolbar sits inside the message box, under the text: the session
/// actions fold into the ⋯ menu, the selectors follow, and ⚡ ☰ ⚙ sit at the right end. Off by default.
/// </summary>
public bool CompactChatToolbar { get; set; }

/// <summary>
/// If true, the native chat tabs open when a solution (or folder) was last closed come back the
/// next time it opens, each resuming its conversation. Claude Code, Codex and Devin only — the
/// agents that can resume. Off by default (v277.0). It replaced the v262.0 setting
/// <c>ReopenChatTabsOnSolutionOpen</c>, which was on by default, under a new name so existing
/// installs start with it off too; see <c>DropRetiredReopenChatTabsSetting</c>.
/// </summary>
public bool ReopenChatTabsWithSolution { get; set; }

/// <summary>
/// The chat tabs to reopen, keyed by workspace directory (lowercase), in tab order with the main
/// chat first. Rewritten whenever a tab's conversation id becomes known or a tab is closed.
/// </summary>
public System.Collections.Generic.Dictionary<string, System.Collections.Generic.List<SavedChatTab>> WorkspaceChatTabs { get; set; } =
    new System.Collections.Generic.Dictionary<string, System.Collections.Generic.List<SavedChatTab>>();

/// <summary>
/// Language of the native chat's UI: "auto" (the Visual Studio UI language), "en", or a culture
/// code with a translation file (embedded lang/&lt;code&gt;.json or one in
/// %LocalAppData%\ClaudeCodeExtension\lang). Applies to chats opened afterwards. Default "auto".
/// </summary>
public string ChatLanguage { get; set; } = "auto";

/// <summary>
/// If true, a chat tab without a user-assigned name is named after its topic: the first prompt,
/// or an AI-generated title when <see cref="AutoTitleChatTabsWithAi"/> is on. A rename always
/// wins. On by default.
/// </summary>
public bool AutoTitleChatTabs { get; set; } = true;

/// <summary>
/// If true (and <see cref="AutoTitleChatTabs"/> is on), Claude Code chats get their title from a
/// one-shot call to a low-cost model instead of the first words of the prompt. Other agents keep
/// the prompt-based title. On by default.
/// </summary>
public bool AutoTitleChatTabsWithAi { get; set; } = true;

/// <summary>
/// Zoom factor of the native-mode chat tab, set with Ctrl+Scroll. 1.0 is 100%.
/// </summary>
public double NativeChatZoom { get; set; } = 1.0;

/// <summary>
/// Height in pixels of the chat tab's prompt box, set by dragging its top edge.
/// </summary>
public double NativeChatComposerHeight { get; set; } = 72;

