/// </summary>
private void RefreshChatLanguage()
{
    ThreadHelper.ThrowIfNotOnUIThread();

    try
    {
        // RefreshToolbarLayout also redoes the detach caption and copies the promoted buttons'
        // tooltips into every chat composer again (the copies are plain text, not bindings).
        RefreshToolbarLayout();
        UpdateSetWorkingDirectoryMenuHeader();
        UpdateEffortSelection();
        if (InlineWeeklyLabel != null) InlineWeeklyLabel.Text = UI.Loc.Retranslate(InlineWeeklyLabel.Text);
        UpdateInlineUsageStaleNotice();
        UpdateLastPromptHint();
        RefreshAllAttachmentChips();
        if (_gitHubIssuesWindow != null) UI.LocTree.Retranslate(_gitHubIssuesWindow);
    }
    catch (Exception ex)
    {
        Debug.WriteLine($"Panel language refresh failed: {ex.Message}");
    }

    try
    {
        if (ChatTranscript != null)
        {
            ChatTranscript.RefreshLanguage();
            if (IsNativeModeActive)
            {
                UpdateChatComposerState(ChatTranscript);
                if (ChatTranscript.IsWelcomeVisible)
                {
                    ShowChatWelcome(ChatTranscript, null);
                }
            }

            UpdateChatTabCaption();
        }

        List<NativeChatSessionState> sessions;
        lock (_sessionLock)
        {
            sessions = new List<NativeChatSessionState>(_nativeSessions.Values);
        }

        foreach (NativeChatSessionState session in sessions)
        {
            if (session.ChatTranscript == null)
            {
                continue;
            }

            session.ChatTranscript.RefreshLanguage();
            UpdateChatComposerState(session);
            if (session.ChatTranscript.IsWelcomeVisible)
            {
                ShowChatWelcome(session.ChatTranscript, session.WorkspaceOverride ?? session.StartedWorkspace);
            }

            UpdateSessionTabCaption(session);
        }
    }
    catch (Exception ex)
    {
        Debug.WriteLine($"Chat language refresh failed: {ex.Message}");
    }
}

/// <summary>
/// Reads only <see cref="ClaudeCodeSettings.ChatLanguage"/> straight from the settings file, for
/// the constructor: the full <see cref="LoadSettings"/> runs after the XAML is already built. The
/// package also calls it at startup, so command text and restored tool windows come up translated.
/// </summary>
internal static void ApplyChatLanguageFromSettingsFile()

