public WelcomeCardContent WelcomeContent
{
    get { return _welcomeContent; }
    set
    {
        if (_welcomeContent == value)
        {
            return;
        }

        _welcomeContent = value;
        ApplyWelcomeTipsVisibility();
        QueueWelcomeLayoutRefresh();
    }
