196	            });
197	            thread.SetApartmentState(ApartmentState.STA);
198	            thread.Start();
199	            thread.Join();
200	
201	            if (failure != null)
202	            {
203	                throw new AssertFailedException(failure.Message, failure);
204	            }
205	        }
