28	        /// <summary>Lowercase, without diacritics ("Ação" → "acao"), whitespace collapsed to single spaces.</summary>
29	        public static string Normalize(string text)
30	        {
31	            if (string.IsNullOrEmpty(text))
32	            {
33	                return string.Empty;
34	            }
35	
36	            string decomposed = text.Normalize(NormalizationForm.FormD);
37	            var sb = new StringBuilder(decomposed.Length);
38	            bool lastWasSpace = true;
39	
40	            foreach (char c in decomposed)
41	            {
42	                if (CharUnicodeInfo.GetUnicodeCategory(c) == UnicodeCategory.NonSpacingMark)
43	                {
